"""Export the trained native subtitle protection head for the D3D11 score pipeline."""

import argparse
import hashlib
from pathlib import Path

import torch


def export(source: Path, output: Path):
    weights = torch.load(source, weights_only=True, map_location="cpu")
    feature_count = weights["layers.0.weight"].shape[1]
    if feature_count not in (42, 50):
        raise ValueError(f"Unsupported native palette input count {feature_count}")
    stages = [(feature_count, 48), (48, 32), (32, 3)]
    lines = [
        "// Generated by tools/sbsbench/export_direct_glyph_palette.py.",
        f"// Source checkpoint SHA-256 {hashlib.sha256(source.read_bytes()).hexdigest()}",
        "// The last two training outputs supervise the separate fill and outline roles.",
        "// Runtime uses their jointly trained protection output.",
        "#ifndef HOST_SBS_DIRECT_GLYPH_PALETTE_WEIGHTS",
        "#define HOST_SBS_DIRECT_GLYPH_PALETTE_WEIGHTS",
        "",
    ]
    for i, (inputs, outputs) in enumerate(stages):
        weight = weights[f"layers.{2 * i}.weight"]
        bias = weights[f"layers.{2 * i}.bias"]
        if weight.shape != (outputs, inputs) or bias.shape != (outputs,):
            raise ValueError(f"Unexpected layer {i} shape")
        if not (torch.isfinite(weight).all() and torch.isfinite(bias).all()):
            raise ValueError(f"Non-finite parameters in layer {i}")
        if i == 2:
            weight, bias = weight[:1], bias[:1]
        for name, values in (("Weight", weight), ("Bias", bias)):
            flat = values.flatten().tolist()
            lines.append(f"static const float Palette{name}{i}[{len(flat)}] = {{")
            for start in range(0, len(flat), 6):
                lines.append("    " + ", ".join(f"{v:.9e}f" for v in flat[start:start + 6]) + ",")
            lines.extend(["};", ""])
    lines.extend([
        f"float PaletteMask(float features[{feature_count}]) {{",
        "    float hidden[48];",
        "    [unroll] for (uint i = 0; i < 48; ++i) {",
        "        float sum = PaletteBias0[i];",
        f"        [unroll] for (uint j = 0; j < {feature_count}; ++j) sum += PaletteWeight0[i * {feature_count} + j] * features[j];",
        "        hidden[i] = max(0.0f, sum);",
        "    }",
        "    float activation[32];",
        "    [unroll] for (uint i = 0; i < 32; ++i) {",
        "        float sum = PaletteBias1[i];",
        "        [unroll] for (uint j = 0; j < 48; ++j) sum += PaletteWeight1[i * 48 + j] * hidden[j];",
        "        activation[i] = max(0.0f, sum);",
        "    }",
        "    float logit = PaletteBias2[0];",
        "    [unroll] for (uint j = 0; j < 32; ++j) logit += PaletteWeight2[j] * activation[j];",
        "    return 1.0f / (1.0f + exp(-logit));",
        "}",
        "#endif",
    ])
    output.write_text("\n".join(lines) + "\n", encoding="utf-8", newline="\n")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("checkpoint", type=Path)
    parser.add_argument("output", type=Path)
    parser.add_argument("--outline-gate", type=Path)
    parser.add_argument("--outline-strength", type=float)
    args = parser.parse_args()
    if (args.outline_gate is None) != (args.outline_strength is None):
        parser.error("--outline-gate and --outline-strength must be used together")
    export(args.checkpoint, args.output)
    if args.outline_gate is not None:
        from export_direct_glyph_outline_gate import insert
        insert(args.output, args.outline_gate, args.outline_strength)
